    def _export_chats_worker(self):
        import glob
        repo = self.repo_path
        self.set_status("Exporting chat digests")
        self.root.after(0, lambda: self._select_tab("console"))
        self.log("\n=== CHAT → MARKDOWN EXPORT ===\n", "mag")
        self.log("Digesting Claude Code + GitHub Copilot chats for this repo into\n"
                 "grafel-chats/ — note: these files CONTAIN chat text (local only).\n",
                 "dim")
        _ws, folders = find_workspace_for(repo)
        folders = folders or [repo]
        outdir = os.path.join(repo, "grafel-chats")
        os.makedirs(outdir, exist_ok=True)
        made = []

        def trim(t, n=400):
            t = " ".join((t or "").split())
            return t[:n] + ("…" if len(t) > n else "")

        def write(name, title, meta, exchanges):
            fp = os.path.join(outdir, name)
            try:
                with open(fp, "w", encoding="utf-8") as f:
                    f.write(f"# {title}\n\n{meta}\n\n")
                    for i, (u, a, usage) in enumerate(exchanges, 1):
                        f.write(f"## Prompt {i}\n\n")
                        if u:
                            f.write(f"**User:** {u}\n\n")
                        if a:
                            f.write(f"**Agent:** {a}\n\n")
                        if usage:
                            f.write(f"*{usage}*\n\n")
            except OSError as e:
                self.log(f"   ✗ {name}: {e}\n", "err")
                return
            made.append((name, title, len(exchanges)))
            self.log(f"   ✓ {name}  ({len(exchanges)} prompts)\n", "ok")

        def claude_exchanges(fp):
            ex, cur_u, cur_a, tok, seen = [], None, [], 0, set()

            def close():
                if cur_u is not None:
                    ex.append((trim(cur_u), trim(" ".join(cur_a)),
                               f"~{tok:,} tokens" if tok else ""))
            try:
                fh = open(fp, encoding="utf-8", errors="ignore")
            except OSError:
                return []
            with fh:
                for line in fh:
                    try:
                        obj = json.loads(line)
                    except ValueError:
                        continue
                    msg = obj.get("message") or {}
                    role = msg.get("role")
                    if obj.get("type") == "user" and role == "user":
                        c = msg.get("content")
                        txt = c if isinstance(c, str) else next(
                            (b.get("text") for b in (c or [])
                             if isinstance(b, dict) and b.get("type") == "text"),
                            None)
                        if txt:
                            close()
                            cur_u, cur_a, tok = txt, [], 0
                    elif role == "assistant":
                        mid, u = msg.get("id"), msg.get("usage") or {}
                        if mid and u and mid not in seen:
                            seen.add(mid)
                            tok += sum(u.get(k) or 0 for k in
                                       ("input_tokens", "cache_read_input_tokens",
                                        "cache_creation_input_tokens",
                                        "output_tokens"))
                        for b in msg.get("content") or []:
                            if (isinstance(b, dict) and b.get("type") == "text"
                                    and b.get("text")):
                                cur_a.append(b["text"])
            close()
            return ex[:200]

        def copilot_exchanges(fp):
            reqs = []

            def ensure(i):
                while len(reqs) <= i:
                    reqs.append({"u": "", "a": [], "pt": 0, "ct": 0, "cr": 0.0})

            def add_resp(i, parts):
                ensure(i)
                for p in parts or []:
                    if (isinstance(p, dict) and isinstance(p.get("value"), str)
                            and p.get("kind") in (None, "markdownContent")):
                        reqs[i]["a"].append(p["value"])
            try:
                fh = open(fp, encoding="utf-8", errors="ignore")
            except OSError:
                return []
            with fh:
                for line in fh:
                    try:
                        obj = json.loads(line)
                    except ValueError:
                        continue
                    kind, k, v = obj.get("kind"), obj.get("k"), obj.get("v")
                    if kind == 0 and isinstance(v, dict):
                        for i, r in enumerate(v.get("requests") or []):
                            ensure(i)
                            reqs[i]["u"] = ((r.get("message") or {}).get("text")
                                            or "")
                            add_resp(i, r.get("response"))
                    elif kind == 2 and k == ["requests"] and isinstance(v, list):
                        for r in v:
                            reqs.append({"u": ((r.get("message") or {}).get("text")
                                               or ""), "a": [], "pt": 0, "ct": 0,
                                         "cr": 0.0})
                    elif (kind == 2 and isinstance(k, list) and len(k) == 3
                          and k[0] == "requests" and k[2] == "response"
                          and isinstance(k[1], int)):
                        add_resp(k[1], v)
                    elif (kind == 1 and isinstance(k, list) and len(k) == 3
                          and k[0] == "requests" and isinstance(k[1], int)):
                        fld = {"promptTokens": "pt", "completionTokens": "ct",
                               "copilotCredits": "cr"}.get(k[2])
                        if fld:
                            ensure(k[1])
                            reqs[k[1]][fld] = v or 0
            out = []
            for r in reqs:
                usage = []
                if r["pt"] or r["ct"]:
                    usage.append(f"tokens: prompt {r['pt']:,} · "
                                 f"completion {r['ct']:,}")
                if r["cr"]:
                    usage.append(f"credits: {r['cr']:.2f}")
                out.append((trim(r["u"]), trim(" ".join(r["a"])),
                            " · ".join(usage)))
            return out[:200]

        # --- Claude Code sessions ---
        for fld in folders:
            d = claude_log_dir(fld)
            if not d:
                continue
            for fp in glob.glob(os.path.join(d, "*.jsonl")):
                ex = claude_exchanges(fp)
                if ex:
                    day = time.strftime("%Y-%m-%d",
                                        time.localtime(os.path.getmtime(fp)))
                    sid = os.path.basename(fp).split(".")[0][:8]
                    write(f"claude-{day}-{sid}.md",
                          f"Claude Code chat — {os.path.basename(fld)} ({day})",
                          f"Source: `{fp}`", ex)

        # --- VS Code Copilot Chat sessions ---
        for s in list_vscode_copilot_sessions(folders):
            ex = copilot_exchanges(s["file"])
            if ex:
                day = time.strftime("%Y-%m-%d", time.localtime(s["mtime"]))
                sid = os.path.basename(s["file"]).split(".")[0][:8]
                write(f"copilot-vscode-{day}-{sid}.md",
                      f"Copilot Chat (VS Code) — {s['name']} ({day})",
                      f"Source: `{s['file']}`", ex)

        # --- Copilot CLI sessions (session-store.db) ---
        db = os.path.join(os.path.expanduser("~"), ".copilot", "session-store.db")
        want = {os.path.normcase(os.path.normpath(f)) for f in folders}
        if os.path.exists(db):
            try:
                import sqlite3
                con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
                cur = con.cursor()
                for sid, cwd, summ, upd in cur.execute(
                        "SELECT id, cwd, summary, updated_at FROM sessions"):
                    if (not cwd or os.path.normcase(os.path.normpath(cwd))
                            not in want):
                        continue
                    ex = [(trim(u), trim(a), "") for u, a in cur.execute(
                        "SELECT user_message, assistant_response FROM turns "
                        "WHERE session_id=? ORDER BY turn_index", (sid,))][:200]
                    if ex:
                        day = (upd or "")[:10] or "unknown"
                        meta = f"Source: Copilot CLI session `{sid}`"
                        if summ:
                            meta += f"\n\nSession summary: {trim(summ, 300)}"
                        write(f"copilot-cli-{day}-{sid[:8]}.md",
                              f"Copilot CLI chat — {os.path.basename(cwd)} ({day})",
                              meta, ex)
                con.close()
            except Exception as e:
                self.log(f"   (Copilot CLI store read failed: {e})\n", "dim")

        if not made:
            self.log("No AI chats found for this repo/workspace yet.\n", "err")
            self.set_status("No chats to export")
            return
        try:
            with open(os.path.join(outdir, "index.md"), "w",
                      encoding="utf-8") as f:
                f.write("# AI chat digests for this repo\n\n"
                        "Agents: read the relevant digest below instead of "
                        "replaying full chat logs.\n\n")
                for name, title, n in sorted(made):
                    f.write(f"- [{title}]({name}) — {n} prompts\n")
        except OSError:
            pass
        self.log(f"\n✓ {len(made)} chat digests written to "
                 f"{outdir}\\\n", "ok")
        self.log("  Point your agent at grafel-chats/index.md to resume context "
                 "cheaply.\n", "dim")
        self.set_status(f"Chat export: {len(made)} digests")

